        Undo(row!);C.Execute("UPDATE deed SET status=$p0,rumour_at=NULL WHERE id=$p1",how=="forgiven"?"forgiven":"returned",id);Home(row!);C.Log(player,"gave_back",reference,$"Jef gave {thing} back to {Name(owner)}.");
        if(how is "gave"or"caught"){Memory(player,owner,how=="gave"?$"Jef gave my {thing} back when I asked. Still, he took it.":$"I caught Jef with my {thing} and took it back off him.",how=="gave"?4:6,$"Jef took {Name(owner)}'s {thing} and gave it back when asked",-1);var ledger=State(player,"deed_trust_back")as JsonObject??new();if(how=="gave"&&N(row,"seen")>0&&N(ledger,owner)!=Day){ledger[owner]=Day;C.SetPlayerState(player,"deed_trust_back",ledger);Trust(player,owner,1);}}
