    public static double PickChance(int age,double facing,string act,bool busy,double crowd,int skill,string trade)
    {
        double p=age<12?.35:age<25?.5:age<40?.38:age<55?.28:age<65?.2:.12;p*=facing>.3?1.6:facing<-.3?.6:1;p*=act=="tavern"?.6:act=="market"?.8:1;p*=busy?.7:1;p*=1/(1+.12*Math.Max(0,Math.Clamp(crowd,0,20)-2));p*=1-.04*Math.Clamp(skill,0,5);p*=trade=="thief"?1.5:trade=="police"?1.8:1;return Math.Clamp(p,.03,.95);
    }
    private JsonObject PickPocket(NativeServiceRequest r)=>C.Atomic(()=>
    {
