        int skill=(int)V(State(player,"pick_skill"));bool felt=C.Roll()<PickChance((int)N(resident,"age"),Math.Clamp(N(r.Body,"facing"),-1,1),NativeShops.Activity(resident,Day,Hour).act,r.Bool("busy"),N(r.Body,"crowd"),skill,S(resident,"trade"));var saw=new JsonArray();var suspects=new JsonArray();double light=Light(x,z,r.Bool("lantern")),cover=1/(1+.12*Math.Max(0,Math.Clamp(N(r.Body,"crowd"),0,20)-2));
        foreach(var w in Witnesses(r.Body,id)){if(S(w,"id")==id)continue;var p=Resident(S(w,"id"));if(S(p,"trade")=="thief")continue;double chance=SeeChance(N(w,"d"),B(w,"los"),N(w,"facing"),false,light,r.Bool("crouch"),Sight,S(p,"trade"),(int)N(p,"age",40))*.6*cover,roll=C.Roll();if(roll<chance)saw.Add(w!.DeepClone());else if(chance>.02&&roll<chance*1.8&&N(w,"d")<20)suspects.Add(w!.DeepClone());}
        int coins=felt?0:Math.Clamp((int)Math.Floor(2+N(resident["stats"],"wealth")*(.8+C.Roll()*2.2)+.5),1,60);double itemRoll=felt?.5:C.Roll();string? item=felt?null:N(resident["stats"],"wealth")>=7&&itemRoll<.18?"pocket_watch":itemRoll>.88?"handkerchief":null;if(C.Scalar<int>("SELECT COUNT(*) FROM item WHERE player_id=$p0",player)>=6)item=null;int? itemId=null;if(item!=null){C.Execute("INSERT INTO item(kind,job_id,player_id) VALUES($p0,NULL,$p1)",item,player);itemId=C.Scalar<int>("SELECT last_insert_rowid()");}if(coins>0)C.Execute("UPDATE player SET money_c=money_c+$p0 WHERE id=$p1",coins,player);if(felt)saw.Add(new JsonObject{["id"]=id,["d"]=d,["los"]=true,["facing"]=1,["owner"]=true});
        int deed=Record(player,"purse",item??"coins","pocket:"+id,id,x,z,saw,itemId,saw.Count>0?null:Minute+20+(int)(C.Roll()*40),coins);if(saw.Count==0)C.SetPlayerState(player,"pick_skill",skill+1);C.Log(player,"picked_pocket","pocket:"+id,$"Jef tried {Name(id)}'s pocket{(felt?", and the hand was felt":$" and took {coins} centimes")}.");var response=saw.Count>0?Reactions(player,deed,saw):new JsonObject{["police"]=false,["reaction"]=null,["reactions"]=new JsonArray()};Suspects(player,deed,suspects);if(saw.Count==0)Memory(player,id,"My pocket was picked in the street. I never saw who.",3);
